  if(!empty($f['video_url']))$detail['videoUrl']=esc_url_raw($f['video_url']);
  $rawVisit=gj_is_nepali()?(get_field('visit_notes_ne',$id,false)?:get_field('visit_notes',$id,false)):get_field('visit_notes',$id,false);if(str_contains($rawVisit?:'','trip-card'))$detail['visitHtml']=gj_rich_layout($rawVisit);$detail['originalGardenLayout']=get_post_meta($id,'_gj_import_key',true)==='Godawari Botanical Garden';
  if(!empty($f['bus_source_url']))$detail['transportLinks']=[[[esc_html($f['bus_source_label']),esc_url_raw($f['bus_source_url'])]],[]];
  if(!empty($f['transport_pin_query']))$detail['transportPin']=[$f['transport_pin_query'],$f['transport_pin_label']];
  unset($detail);
  if(!empty($f['facilities']))$out['tripDetails'][$name]['visit'][]=['Facilities and accessibility',[esc_html($f['facilities'])]];
 }
 $sourceOrder=array_flip(array_column($seed['places'],0));usort($out['places'],fn($a,$b)=>($sourceOrder[$a[0]]??PHP_INT_MAX)<=>($sourceOrder[$b[0]]??PHP_INT_MAX));
 // The original city cards group nearby sights; honor stored taxonomy first.
 foreach(['Kathmandu','Lalitpur','Bhaktapur','Banepa','Panauti','Dhulikhel']as$city){$original=$seed['citySightseeing'][$city]??[];foreach($original as$name)if(isset($out['urls'][$name])&&!in_array($name,$out['citySightseeing'][$city]??[],true))$out['citySightseeing'][$city][]=$name;}
 $cityOrder=gj_option('home_cities',[]);$cityNames=[];foreach($cityOrder as$termId){$term=get_term($termId,'place_city');if($term&&!is_wp_error($term))$cityNames[]=$term->name;}if(!$cityNames)$cityNames=['Kathmandu','Lalitpur','Bhaktapur','Banepa','Panauti','Dhulikhel'];foreach($cityNames as$cityName){$cityTerm=get_term_by('name',$cityName,'place_city');$sights=$cityTerm?get_field('city_sights','place_city_'.$cityTerm->term_id):[];if($sights){$out['citySightseeing'][$cityName]=[];foreach($sights as$sightId)if(isset($names[$sightId]))$out['citySightseeing'][$cityName][]=$names[$sightId];}}$out['citySightseeing']=array_intersect_key(array_replace(array_fill_keys($cityNames,[]),$out['citySightseeing']),array_fill_keys($cityNames,true));
 foreach(get_posts(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>-1])as$p){$image=get_post_thumbnail_id($p->ID);if(!$image)continue;$out['postUrls'][$p->post_name]=get_permalink($p->ID);$out['blogPosts'][]=['slug'=>$p->post_name,'title'=>esc_html($p->post_title),'category'=>esc_html(implode(', ',wp_get_post_categories($p->ID,['fields'=>'names']))),'photo'=>'media-'.$image,'intro'=>esc_html($p->post_excerpt),'sections'=>[],'places'=>[],'sources'=>[],'html'=>apply_filters('the_content',$p->post_content)];}
 foreach(['index'=>'','explore'=>'explore','blog'=>'blog','post'=>'blog','about'=>'about','contact'=>'contact','photo-credits'=>'photo-credits','privacy-policy'=>'privacy-policy','terms-of-use'=>'terms-of-use','disclaimer'=>'disclaimer','destination'=>'explore']as$file=>$slug)$out['pages'][$file.'.html']=gj_home_url('/'.($slug?$slug.'/':''));
 $featured=gj_option('featured_destinations',[]);foreach($featured as$id)if(isset($names[$id]))$out['featured'][]=$names[$id];if(!$out['featured'])$out['featured']=array_slice(array_values(array_unique($names)),0,6);
 $banners=gj_option('home_banners',[]);foreach($banners as$id)if(isset($names[$id]))$out['bannerPlaces'][]=$names[$id];if(!$out['bannerPlaces'])$out['bannerPlaces']=array_values(array_filter(['Nagarkot','Chandragiri Hills','Panauti','Kulekhani','Bheda Farm'],fn($n)=>isset($out['urls'][$n])));
 if(!$out['bannerPlaces'])$out['bannerPlaces']=array_slice(array_values($names),0,1);
 if(is_singular('destination'))$out['currentPlace']=gj_canonical_title(get_queried_object_id());if(is_singular('post'))$out['currentPost']=get_post_field('post_name',get_queried_object_id());
 if(is_tax(['outing','place_city','place_type'])){$term=get_queried_object();$out['archivePlaces']=array_map(fn($p)=>gj_canonical_title($p->ID),get_posts(['post_type'=>'destination','post_status'=>'publish','posts_per_page'=>-1,'tax_query'=>[['taxonomy'=>$term->taxonomy,'terms'=>$term->term_id]]]));$ne=gj_is_nepali();$out['archiveTitle']=$term->taxonomy==='place_city'?($ne?$term->name.'मा घुम्ने ठाउँ':'Places to visit in '.$term->name):($ne?$term->name.' सम्बन्धी घुम्ने ठाउँ':$term->name.' outings');}
