// Keep discovery data for search, but send full editorial detail only for this page.
function gj_design_runtime_data(){
 $data=gj_design_data();$current=$data['currentPlace']??'';$post=$data['currentPost']??'';
 foreach(['tripDetails','destinationGalleries','dayPlans']as$key)$data[$key]=$current&&isset($data[$key][$current])?[$current=>$data[$key][$current]]:(object)[];
 foreach($data['destinationGuides']as$name=>$guide)if($name!==$current)$data['destinationGuides'][$name]=isset($guide['picnicPoint'])?['picnicPoint'=>$guide['picnicPoint']]:(object)[];
 foreach($data['blogPosts']as&$entry)if(($entry['slug']??'')!==$post)unset($entry['html']);unset($entry);
 if(!is_page('photo-credits')){
  $keys=array_merge(array_column($data['places'],0),array_column($data['blogPosts'],'photo'),['Dining','Kulekhani']);
  if($current){$detail=$data['tripDetails'][$current]??[];$keys=array_merge($keys,$detail['photos']??[],[$detail['featurePhoto']??'']);foreach($detail['activities']??[]as$activity)$keys[]=$activity[3]??'';}
  $data['photos']=array_intersect_key($data['photos'],array_fill_keys($keys,true));
 }
 if(!is_front_page()&&!is_page('photo-credits'))$data['bannerPhotos']=(object)[];
 return $data;
}
function gj_design_cards_html($names,$data=null){$data=$data?:gj_design_data();$html='';foreach($names as$name){$place=null;foreach($data['places']as$p)if($p[0]===$name){$place=$p;break;}if(!$place)continue;$photo=$data['photos'][$name]??null;$html.='<div class="col" data-reveal="fade-up"><a class="place page-link" href="'.esc_url($data['urls'][$name]).'" data-place="'.esc_attr($name).'"><span class="art">'.($photo?'<img src="'.esc_url($photo['src']).'" alt="'.esc_attr($photo['alt']).'" loading="lazy">':'').'</span><span class="info"><span class="meta">'.esc_html($place[1]).'</span><strong>'.esc_html($name).'</strong><span class="card-foot">'.esc_html(implode(' · ',array_slice(explode('|',$place[2]),0,2))).' <span aria-hidden="true">↗</span></span></span></a></div>'; }return $html;}
function gj_design_chips_html(){ $out='';foreach(get_terms(['taxonomy'=>'outing','hide_empty'=>true])as$t)$out.='<a class="page-link" href="'.esc_url(get_term_link($t)).'" data-filter="'.esc_attr(gj_canonical_term_name($t)).'">'.esc_html($t->name).'</a>';return $out;}
function gj_design_blog_html($limit=0){$data=gj_design_data();$out='';$posts=$limit?array_slice($data['blogPosts'],0,$limit):$data['blogPosts'];foreach($posts as$p){$photo=$data['photos'][$p['photo']];$out.='<div class="col"><a class="place page-link blog-card" href="'.esc_url($data['postUrls'][$p['slug']]).'"><span class="art"><img src="'.esc_url($photo['src']).'" alt="'.esc_attr($photo['alt']).'" loading="lazy"></span><span class="info"><span class="meta">'.$p['category'].'</span><strong>'.$p['title'].'</strong><span>'.$p['intro'].'</span><span class="meta">Read guide ↗</span></span></a></div>';}return $out;}
function gj_design_dom($html){$doc=new DOMDocument();$previous=libxml_use_internal_errors(true);$doc->loadHTML('<?xml encoding="UTF-8"><div id="gj-fragment">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();libxml_use_internal_errors($previous);return $doc;}
function gj_dom_fill($doc,$xpath,$html){$xp=new DOMXPath($doc);foreach($xp->query($xpath)as$node){while($node->firstChild)$node->removeChild($node->firstChild);$fragment=gj_design_dom($html);$root=$fragment->getElementById('gj-fragment');foreach(iterator_to_array($root->childNodes)as$child)$node->appendChild($doc->importNode($child,true));}}
function gj_dom_html($doc){$out='';foreach($doc->getElementById('gj-fragment')->childNodes as$child)$out.=$doc->saveHTML($child);return $out;}
function gj_design_template($name){
 $data=gj_design_data();$doc=gj_design_dom(file_get_contents(get_template_directory().'/views/'.$name.'.html'));$xp=new DOMXPath($doc);
 if($name==='index'){
  $slides='';foreach($data['bannerPlaces']as$i=>$place){$photo=$data['bannerPhotos'][$place]??$data['photos'][$place];$slides.='<div class="swiper-slide"><img '.($i?'data-banner-src="':'src="').esc_url($photo['src']).'" alt="'.esc_attr($photo['alt']).'" '.($i?'loading="lazy"':'fetchpriority="high"'.gj_responsive_attributes($photo)).'></div>';}
  gj_dom_fill($doc,'//*[@id="gj-banner-slides"]',$slides);gj_dom_fill($doc,'//*[@id="gj-home-chips"]',gj_design_chips_html());gj_dom_fill($doc,'//*[@id="gj-featured"]',gj_design_cards_html($data['featured'],$data));gj_dom_fill($doc,'//*[@id="gj-family-trips"]',gj_design_cards_html(['Kathmandu Fun Park','Central Zoo','Natural History Museum'],$data));gj_dom_fill($doc,'//*[@id="gj-blog-posts"]',gj_design_blog_html(3));
  $cities='';foreach($data['citySightseeing']as$city=>$names){$photo=$data['photos'][$names[0]]??null;if(!$photo)continue;$cities.='<div class="col"><a class="place city-card page-link" data-city="'.esc_attr($city).'" href="'.esc_url(add_query_arg('city',$city,gj_home_url('/explore/'))).'"><span class="art"><img src="'.esc_url($photo['src']).'" alt="" loading="lazy"></span><span class="info"><strong>'.esc_html($city).'</strong><span class="card-foot"><span>'.count($names).' places to see</span><span aria-hidden="true">↗</span></span></span></a></div>';}
  gj_dom_fill($doc,'//*[@id="gj-cities"]',$cities);foreach($xp->query('//*[@id="gj-dining-image"]')as$n){$n->setAttribute('src',$data['photos']['Dining']['src']);}
  if(gj_option('home_title')&&gj_option('home_title')!=='Where shall we go today?')gj_dom_fill($doc,'//*[contains(@class,"hero-copy")]/h1',esc_html(gj_option('home_title')));
  if(gj_option('home_eyebrow'))gj_dom_fill($doc,'//*[contains(@class,"hero-copy")]/p',esc_html(gj_option('home_eyebrow')));
 }
 if($name==='blog')gj_dom_fill($doc,'//*[@id="gj-blog-posts"]',gj_design_blog_html());
 if($name==='explore'){
  $names=$data['archivePlaces']??array_column($data['places'],0);$requestedCity=$data['city']??sanitize_text_field(wp_unslash($_GET['city']??''));if(isset($data['citySightseeing'][$requestedCity]))$names=$data['citySightseeing'][$requestedCity];$requestedCategory=$data['category']??sanitize_text_field(wp_unslash($_GET['category']??''));if($requestedCategory&&$requestedCategory!=='All'){$allowed=[];foreach($data['places']as$place)if(in_array($place[0],$names,true)&&($place[1]===$requestedCategory||in_array($requestedCategory,explode('|',$place[2]),true)))$allowed[]=$place[0];$names=$allowed;}
  $q=sanitize_text_field(wp_unslash($_GET['q']??''));if($q)$names=array_values(array_filter($names,fn($n)=>stripos($n,$q)!==false || (gj_is_nepali() && mb_stripos(gj_translate_label($n),$q)!==false)));
  gj_dom_fill($doc,'//*[@id="gj-results-title"]',esc_html($data['archiveTitle']??$data['resultsTitle']??'Explore nearby'));
  gj_dom_fill($doc,'//*[@id="gj-list"]',gj_design_cards_html($names,$data));gj_dom_fill($doc,'//*[@id="gj-filters"]',gj_design_chips_html());gj_dom_fill($doc,'//*[@id="gj-count"]',count($names).' places');
 }
 if($name==='post'){$id=get_queried_object_id();gj_dom_fill($doc,'//*[@id="gj-post-title"]',esc_html(get_the_title($id)));gj_dom_fill($doc,'//*[@id="gj-post-intro"]',esc_html(get_the_excerpt($id)));gj_dom_fill($doc,'//*[@id="gj-post-body"]',apply_filters('the_content',get_post_field('post_content',$id)));foreach($xp->query('//*[@id="gj-post-image"]')as$n){$n->setAttribute('src',get_the_post_thumbnail_url($id,'large'));$n->removeAttribute('hidden');}}
 gj_responsive_fragment($doc,array_merge($data['photos'],$data['bannerPhotos']));
 return gj_legacy_links(gj_dom_html($doc));
}
function gj_design_trip_html(){
 $id=get_queried_object_id();$name=gj_canonical_title($id);$data=gj_design_data();$details=$data['tripDetails'][$name];$guide=$data['destinationGuides'][$name];
 $raw=file_get_contents(get_template_directory().'/views/destination.html');preg_match('~<template[^>]*>(.*)</template>~s',$raw,$match);$doc=gj_design_dom($match[1]);$xp=new DOMXPath($doc);
 $fill=function($slot,$html)use($doc){gj_dom_fill($doc,'//*[@data-trip-'.$slot.']',$html);};
 $fill('title',esc_html($name));$fill('location',esc_html(strtoupper($details['location'])));$fill('intro',esc_html($guide['summary']));
 $slides='';foreach($details['photos']as$i=>$key){$photo=$data['photos'][$key];$slides.='<div class="swiper-slide"><img src="'.esc_url($photo['src']).'" data-trip-photo="'.esc_attr($key).'" alt="'.esc_attr($photo['alt']).'" '.($i?'loading="lazy"':'fetchpriority="high"').'></div>';}$fill('slides',$slides);
 $facts='';foreach($details['facts']as$f)$facts.='<div><dt>'.$f[0].'</dt><dd>'.$f[1].'</dd><dd>'.$f[2].'</dd></div>';$fill('facts',$facts);
 $activities='';foreach($details['activities']as$a){$photo=$data['photos'][$a[3]]??null;$activities.='<li>'.($photo?'<img class="trip-stop-photo" src="'.esc_url($photo['src']).'" alt="'.esc_attr($photo['alt']).'" loading="lazy">':'').'<div><h3>'.$a[0].'</h3><p>'.$a[1].'</p><a class="trip-inline-link" href="'.esc_url($a[2]).'" rel="noopener">View on map ↗</a></div></li>';}$fill('activities',$activities);
 $sources='';foreach($details['sources']as$s)$sources.='<a class="trip-inline-link" href="'.esc_url($s[1]).'" rel="noopener">'.$s[0].' ↗</a>';$fill('feature-link',$sources);
 foreach($xp->query('//*[@data-trip-feature]')as$n){if(isset($details['featurePhoto'])||isset($details['photos'][1])){$photo=$data['photos'][$details['featurePhoto']??$details['photos'][1]];gj_dom_fill($doc,'//*[@data-trip-feature]','<img src="'.esc_url($photo['src']).'" alt="'.esc_attr($photo['alt']).'" loading="lazy"><figcaption>'.esc_html($photo['alt']).'</figcaption>');}else$n->parentNode->removeChild($n);}
 if(!empty($guide['history'])){$fill('history',esc_html($guide['history'][0]));$fill('history-source','<a href="'.esc_url($guide['history'][2]).'">'.esc_html($guide['history'][1]).'</a>');foreach($xp->query('//*[@id="gj-history" or @data-trip-history-jump]')as$n)$n->removeAttribute('hidden');}
 foreach($xp->query('//*[@id="gj-vlog-title"]')as$n){if(!empty($details['videoUrl'])){foreach($xp->query('.//iframe',$n)as$frame)$frame->setAttribute('data-consent-src',$details['videoUrl']);}else$n->parentNode->removeChild($n);}
 $visit=$details['visitHtml']??'';if(!$visit)foreach($details['visit']as$v)$visit.='<div class="trip-card"><h3>'.esc_html($v[0]).'</h3>'.implode('',$v[1]).'</div>';$fill('visit',$visit);
 $transport='';foreach($details['transport']as$t)$transport.='<div><h3>'.$t[0].'</h3><p>'.$t[1].'</p></div>';$fill('transport',$transport.'<div class="trip-text-links" data-trip-travel-links></div>');
 $map='https://www.google.com/maps/search/?api=1&query='.rawurlencode(gj_value('address',$id,$name));foreach($xp->query('//*[@data-trip-directions or @data-trip-map-link]')as$n)$n->setAttribute('href',$map);
 $fill('map','<a class="action trip-map-link" href="'.esc_url($map).'" target="_blank" rel="noopener">Open location in Google Maps ↗</a>');
 $meals='';foreach($details['meals']??[]as$m)$meals.='<article class="trip-card"><p class="eyebrow">'.$m[0].'</p><h3>'.$m[1].'</h3><p>'.$m[2].'</p>'.($m[3]?'<a href="'.esc_url($m[3]).'">Visit website ↗</a>':'').'</article>';$fill('meals',$meals);$fill('meal-note',esc_html($details['mealNote']??''));$stayHtml='';foreach($details['stays']??[]as$stay)$stayHtml.='<li><strong>'.$stay[0].'</strong> <span>'.$stay[1].'</span> <a href="'.esc_url($stay[2]).'">Hotel website ↗</a></li>';$fill('stays',$stayHtml);$fill('food-links','<a class="page-link" href="'.esc_url('https://www.google.com/maps/search/?api=1&query='.rawurlencode('Restaurants near '.$name)).'">Find nearby restaurants ↗</a>');
 $plan='';foreach($details['plan']as$p)$plan.='<li><strong>'.$p[0].'</strong><span>'.$p[1].'</span></li>';$fill('plan',$plan);$fill('nearby-note',esc_html($details['nearbyNote']??''));$nearbyHtml='';foreach($details['nearby']as$nearby)$nearbyHtml.='<a class="page-link" href="'.esc_url($nearby[2]).'">'.$nearby[1].' ↗</a>';$fill('nearby-links',$nearbyHtml);
 $related=array_slice(array_values(array_diff(array_column($data['places'],0),[$name])),0,3);$fill('related',gj_design_cards_html($related,$data));
 gj_responsive_fragment($doc,$data['photos']);
 $html='<section data-screen="detail" class="destination-trip">'.gj_dom_html($doc).'</section>';
 $html.=$raw; // Retain the inert template for the original interactive renderer.
 // Remove its empty screen; only the SSR screen above is visible before enhancement.
 $html=preg_replace('~<section data-screen="detail"></section>~','',$html);
 return gj_legacy_links($html);
}
function gj_footer_navigation(){
 $locations=get_nav_menu_locations();$items=wp_get_nav_menu_items($locations['footer']??0)?:[];
 echo '<div class="footer-navigation"><div class="footer-links">';foreach($items as$i=>$item){if($i===3)echo '</div><div class="footer-links footer-legal" aria-label="Policies">';$class=$i===2?'footer-credits':($i<3?'footer-link':'');$current=is_page()&&untrailingslashit(get_permalink(get_queried_object_id()))===untrailingslashit($item->url);echo '<a class="'.$class.'" href="'.esc_url($item->url).'" data-reveal="fade-up"'.($current?' aria-current="page"':'').'>'.esc_html($item->title).'</a>';}echo '<button class="footer-cookie-preferences" type="button" data-cookie-preferences hidden>Cookie preferences</button></div></div>';
}
function gj_credit_items(){
 $data=gj_design_data();$unique=[];foreach(array_merge(array_values($data['photos']),array_values($data['bannerPhotos']??[]))as$photo){if(empty($photo['author'])||empty($photo['source'])&&empty($photo['commons']))continue;$unique[$photo['src']]=$photo;}return array_values($unique);
}
function gj_credits_html(){
 $html='';foreach(gj_credit_items()as$p){$source=$p['source']??$p['commons']??'';$license=$p['license']??'';$credit='';if($license==='PD')$credit='by '.esc_html($p['author']).' · Public domain';elseif($license){$by=$license==='BY';$label=$by?'CC BY 4.0':'CC BY-SA '.$license;$url='https://creativecommons.org/licenses/'.($by?'by/4.0/':'by-sa/'.rawurlencode($license).'/');$credit='by '.esc_html($p['author']).' · <a href="'.esc_url($url).'">'.esc_html($label).'</a>';}else$credit='· Photo source: '.esc_html($p['author']);$html.='<li><span class="credit-thumbnail"><img src="'.esc_url($p['src']).'" width="64" height="48" alt="" loading="lazy" decoding="async"></span><div><a href="'.esc_url($source).'">'.esc_html($p['alt']).'</a> '.$credit.'</div></li>';}return $html;
}
function gj_social_icons(){
 $doc=gj_design_dom(file_get_contents(get_template_directory().'/views/social-icons.html'));$xp=new DOMXPath($doc);foreach(iterator_to_array($xp->query('//span[contains(@class,"social-icon")]'))as$span){$name=$span->getAttribute('aria-label');$url=gj_option('social_'.strtolower($name));if(!$url){$span->parentNode->parentNode->removeChild($span->parentNode);continue;}$link=$doc->createElement('a');foreach(['class','aria-label','title']as$attr)$link->setAttribute($attr,$span->getAttribute($attr));$link->setAttribute('href',esc_url_raw($url));$link->setAttribute('target','_blank');$link->setAttribute('rel','noopener noreferrer');while($span->firstChild)$link->appendChild($span->firstChild);$span->parentNode->replaceChild($link,$span);}echo gj_dom_html($doc);
}

function gj_rich_layout($html){
 // Editor padding outside the cards becomes an anonymous CSS grid item.
 $html=preg_replace('~\A(?:\s|\x{00A0}|&nbsp;|&#0*160;|&#x0*a0;)+|(?:\s|\x{00A0}|&nbsp;|&#0*160;|&#x0*a0;)+\z~iu','',$html);
 $html=preg_replace('~<span\b[^>]*class=[\"\']link-arrow[\"\'][^>]*>.*?</span>~s','<span class="link-arrow" aria-hidden="true">↗</span>',$html);return wp_kses_post($html);}

function gj_restore_page_reveals($content,$slug){$path=get_template_directory().'/views/'.$slug.'.html';if(!file_exists($path))return $content;$reference=gj_design_dom(file_get_contents($path));$actual=gj_design_dom($content);$refXpath=new DOMXPath($reference);$actualXpath=new DOMXPath($actual);foreach($refXpath->query('//*[@data-reveal]')as$node){$target=$actualXpath->query($node->getNodePath())->item(0);if($target&&$target->nodeName===$node->nodeName&&$target->getAttribute('class')===$node->getAttribute('class'))$target->setAttribute('data-reveal',$node->getAttribute('data-reveal'));}return gj_dom_html($actual);}
